function commit(next,label='',type='change',itemId='',record=true){if(record){const before=JSON.stringify({wishlist:db.wishlist,owned:db.owned,priority:db.priority,prices:db.prices,tiers:db.tiers,priorityViews:db.priorityViews,vp:db.vp});next.undoStack=[...(db.undoStack||[]),before].slice(-50);next.redoStack=[];if(label)next.history=[{id:Date.now()+Math.random(),type,skinId:itemId,label,time:new Date().toISOString()},...(next.history||[])].slice(0,500)}db=normalized(next);save();render();if(label)toast(label)}
function toggle(bucket,itemId){const exists=db[bucket].includes(itemId),next={...db,[bucket]:exists?db[bucket].filter(x=>x!==itemId):[itemId,...db[bucket]]};if(bucket==='wishlist'&&exists){next.priority=db.priority.filter(x=>x!==itemId);next.priorityViews=cleanPriorityViews(next.priority)};commit(next,`${exists?'Removed from':'Added to'} ${bucket}`,bucket,itemId)}
