function vpSummary(ids){const outstanding=ids.filter(i=>!db.owned.includes(i));let required=0,unknown=0,custom=0;for(const i of outstanding){const p=simPrice(itemById(i));if(p.known){required+=p.value;if(p.custom)custom++}else unknown++}return{required,unknown,custom,owned:ids.length-outstanding.length,remaining:Math.max(0,required-db.vp)}}
