function normCatalog(k,arr){let all=[];if(k==='skins'){for(const w of arr){for(const x of w.skins||[]){if(!x.uuid||/standard|random/i.test(x.displayName||''))continue;all.push(toItem(x,k,w.displayName))}}}else for(const x of arr){if(x&&x.uuid)all.push(toItem(x,k))}return all.sort((a,b)=>a.name.localeCompare(b.name))}
