 if(prefs.state==='fav'&&!isFav||prefs.state==='notfav'&&isFav)return false;
 if(prefs.state==='owned'&&!db.owned.includes(i)||prefs.state==='unowned'&&db.owned.includes(i))return false;
 if(prefs.state==='wish'&&!db.wishlist.includes(i)||prefs.state==='notwish'&&db.wishlist.includes(i))return false;
 if(prefs.state==='sim'&&!db.buyingPlans.some(p=>p.items.includes(i)))return false;
 if(prefs.priceMin!==''&&(price===null||price<Number(prefs.priceMin)))return false;
