app.addEventListener('dragstart',e=>{const row=e.target.closest('[data-sim-drag]');if(row){draggedSimId=row.dataset.simDrag;e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',draggedSimId);return}const target=e.target.closest('[data-priority-drag]');if(!target)return;draggedPriorityId=target.dataset.priorityDrag;e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',draggedPriorityId)});
app.addEventListener('dragover',e=>{if((draggedPriorityId&&e.target.closest('[data-priority-drag]'))||(draggedSimId&&e.target.closest('[data-sim-drag]')))e.preventDefault()});
app.addEventListener('drop',e=>{const dest=e.target.closest('[data-sim-drag]');if(dest&&draggedSimId){e.preventDefault();const p=activeBuyingPlan();if(p)buyingMove(draggedSimId,p.items.indexOf(dest.dataset.simDrag));draggedSimId='';return}const target=e.target.closest('[data-priority-drag]');if(!target||!draggedPriorityId)return;e.preventDefault();let list=priorityItems(),newIndex=list.indexOf(target.dataset.priorityDrag);if(newIndex>=0)priorityMove(draggedPriorityId,newIndex);draggedPriorityId=''});
app.addEventListener('dragend',()=>{draggedPriorityId='';draggedSimId=''});
app.addEventListener('mousedown',e=>{if(e.target.id==='sim-picker-backdrop'){simPicker=null;render()}if(e.target.id==='loadout-picker-backdrop'){loadoutPicker=null;render()}if(e.target.id==='detail-backdrop'){detail=null;render()}if(e.target.id==='bundle-picker-backdrop'){bundlePicker=false;render()}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&(detail||moreOpen||loadoutPicker||simPicker||bundlePicker)){detail=null;moreOpen=false;loadoutPicker=null;simPicker=null;bundlePicker=false;render()}});
app.addEventListener('submit',e=>{e.preventDefault();const form=e.target,f=new FormData(form);
if(form.id==='new-buying-plan'){const name=String(f.get('planName')||'').trim();if(!name)return;const plan={id:id(),name:name.slice(0,70),items:[],balanceOverride:null};db.buyingPlans.push(plan);db.preferences.activeBuyingPlan=plan.id;save();render();toast('Buying plan created')}
else if(form.id==='new-loadout'){let name=String(f.get('name')||'').trim();if(!name)return;let item={id:id(),name,items:{}};db.loadouts.push(item);activeLoadout=item.id;save();render();toast('Loadout created')}
else if(form.id==='new-goal'){const name=String(f.get('goalName')||'').trim(),target=Number(f.get('goalVP'));if(!name||!Number.isFinite(target)||target<1)return;db.goals.push({id:id(),name,target,saved:0});save();render();toast('Savings goal created')}
else if(form.id==='profile-form'){db.name=String(f.get('profileName')||'PLAYER').trim()||'PLAYER';db.vp=Math.max(0,Number(f.get('balance'))||0);save();render();toast('Profile saved')}
else if(form.id==='rarity-form'){for(const r of ['Select','Deluxe','Premium','Exclusive','Ultra'])db.rarityPrices[r]=Math.max(0,Number(f.get('rarity-'+r))||0);save();render();toast('Default prices saved')}
else if(form.id==='preferences-form'){db.preferences={...db.preferences,pageSize:Number(f.get('pageSize'))||18,view:String(f.get('view')||'grid'),density:String(f.get('density')||'comfortable'),reducedMotion:f.get('reducedMotion')!==null};save();render();toast('Preferences saved')}
else if(form.id==='cloud-login'){const submit=e.submitter||document.activeElement;auth(String(submit?.value||'login'),String(f.get('email')||''),String(f.get('password')||''),String(f.get('name')||''))}
});
async function importBackup(file){if(!file)return;try{const imported=JSON.parse(await file.text());if(!imported||typeof imported!=='object'||!Array.isArray(imported.wishlist)||!Array.isArray(imported.owned))throw Error('Not a VALOWISH backup');if(!confirm('Import this VALOWISH backup and replace your current local data?'))return;backupBeforeChange('before-import');db=normalized(imported);save();render();toast('Backup imported; cloud sync pending')}catch(e){toast('Import failed: invalid backup')}}
// v20: automatic multi-device cloud reconciliation with verified, conditional writes.
// Recoverable snapshots are created before ambiguous data is merged; there are no routine review prompts.
function payloadOf(value=db){const x=normalized(value);delete x.undoStack;delete x.redoStack;return x}
function stableValue(value){if(Array.isArray(value))return value.map(stableValue);if(value&&typeof value==='object'){const sorted={};for(const key of Object.keys(value).sort())sorted[key]=stableValue(value[key]);return sorted}return value}
function sameData(a,b){return JSON.stringify(stableValue(a))===JSON.stringify(stableValue(b))}
function payloadSame(a,b){return sameData(payloadOf(a),payloadOf(b))}
function hasContent(value){const x=payloadOf(value),b=payloadOf(blank());return ['wishlist','owned','priority','favorites','history','loadouts','goals','buyingPlans'].some(k=>x[k]?.length)||Object.keys(x.prices).length||Object.keys(x.notes).length||Object.keys(x.tags).length||!sameData(x.priorityViews,{})||x.vp!==b.vp||x.name!==b.name||!sameData(x.rarityPrices,b.rarityPrices)}
function storedBaseline(uid){try{return JSON.parse(localStorage.getItem(CLOUD_META_PREFIX+uid)||'null')}catch{return null}}
function saveBaseline(uid,data,stamp){const r={data:payloadOf(data),updated_at:stamp,confirmed_at:new Date().toISOString()};cloudBaseline=r.data;cloudRemoteStamp=stamp;cloudLastSync=r.confirmed_at;try{localStorage.setItem(CLOUD_META_PREFIX+uid,JSON.stringify(r))}catch(e){console.warn('Cloud sync snapshot could not be cached',e)}}
function backupBeforeChange(label,value=db){try{const key='valowish_recovery_v19_'+Date.now()+'_'+label;localStorage.setItem(key,JSON.stringify({created_at:new Date().toISOString(),label,data:payloadOf(value)}));const keys=Object.keys(localStorage).filter(k=>k.startsWith('valowish_recovery_v19_')).sort();for(const k of keys.slice(0,Math.max(0,keys.length-8)))localStorage.removeItem(k)}catch(e){console.warn('Backup could not be saved:',e)}}
function restoreCloudSnapshot(remote,stamp){if(!payloadSame(db,remote)){backupBeforeChange('before-cloud-restore');db=normalized(remote);save(false)}saveBaseline(cloudUser.id,remote,stamp);cloudStatus='synced';cloudConflict=null;cloudError='';cloudMessage='Cloud data restored on this device';render()}
function mergeMembership(base,left,right){const original=new Set(base||[]),a=new Set(left||[]),b=new Set(right||[]),ordered=[...(left||[]),...(right||[])];return [...new Set(ordered)].filter(id=>original.has(id)?a.has(id)&&b.has(id):a.has(id)||b.has(id))}
const MERGE_MEMBERSHIP=new Set(['wishlist','owned','favorites']);
const MERGE_BY_ID=new Set(['history','loadouts','goals','buyingPlans']);
function mergeOrdered(base,left,right,prefer){
 const first=prefer==='local'?left:right,second=prefer==='local'?right:left,original=new Set(base||[]),a=new Set(left),b=new Set(right);
 return [...new Set([...first,...second])].filter(id=>!original.has(id)||(a.has(id)&&b.has(id)));
}
function merge3(base,left,right,key='',prefer='remote'){
 if(sameData(left,right))return{value:left,conflicts:[]};
 if(sameData(left,base))return{value:right,conflicts:[]};
 if(sameData(right,base))return{value:left,conflicts:[]};
 if((MERGE_MEMBERSHIP.has(key)||key.startsWith('bundleContents.'))&&Array.isArray(left)&&Array.isArray(right))return{value:mergeMembership(base,left,right),conflicts:[]};
 if(MERGE_BY_ID.has(key)&&Array.isArray(left)&&Array.isArray(right)){
  const b=new Map((base||[]).map(x=>[String(x.id),x])),l=new Map(left.map(x=>[String(x.id),x])),r=new Map(right.map(x=>[String(x.id),x]));
  const ids=[...new Set([...l.keys(),...r.keys()])],items=[],conflicts=[];
  for(const id of ids){const old=b.get(id),a=l.get(id),z=r.get(id);
   if(old&&(!a||!z)){if(!a&&!z)continue;const survivor=a||z;if(!sameData(survivor,old))items.push(survivor);continue}
   if(!a||!z){items.push(a||z);continue}
   const merged=merge3(old,a,z,key+'.'+id,prefer);items.push(merged.value);conflicts.push(...merged.conflicts)
  }
  if(key==='history')items.sort((a,b)=>new Date(b.time||0)-new Date(a.time||0));
  return{value:items,conflicts};
 }
 // Ordered ID lists (including per-weapon priority and buying-plan order): keep the newest order,
 // but preserve additions from either device and jointly acknowledged removals.
 if(Array.isArray(left)&&Array.isArray(right)&&left.every(x=>typeof x==='string')&&right.every(x=>typeof x==='string'))return{value:mergeOrdered(base,left,right,prefer),conflicts:[]};

 if((base===null||base===undefined||typeof base==='object')&&left&&right&&!Array.isArray(left)&&!Array.isArray(right)&&typeof left==='object'&&typeof right==='object'){
  const out={},conflicts=[];for(const k of new Set([...Object.keys(base||{}),...Object.keys(left),...Object.keys(right)])){
   const merged=merge3(base?.[k],left[k],right[k],k,prefer);if(merged.value!==undefined)out[k]=merged.value;conflicts.push(...merged.conflicts.map(c=>key?key+'.'+c:c));
  }return{value:out,conflicts};
 }
 // Latest known edit wins for the same scalar. Both full snapshots are preserved locally first.
 return{value:prefer==='local'?left:right,conflicts:[]};
}
async function readCloudRow(){const{data,error}=await cloud.from('valowish_data').select('data,updated_at').eq('user_id',cloudUser.id).maybeSingle();if(error)throw error;return data||null}
async function writeCloudRow(expectedStamp,desired){const when=new Date().toISOString(),uid=cloudUser.id;let result;
 if(expectedStamp){result=await cloud.from('valowish_data').update({data:desired,updated_at:when}).eq('user_id',uid).eq('updated_at',expectedStamp).select('updated_at').maybeSingle()}
 else{result=await cloud.from('valowish_data').insert({user_id:uid,data:desired,updated_at:when}).select('updated_at').maybeSingle()}
 if(result.error){if(result.error.code==='23505')return null;throw result.error}
 return result.data?.updated_at||null;
}
function setSyncConflict(remote,stamp,reason){cloudConflict={remote:payloadOf(remote),stamp,reason};cloudStatus='conflict';cloudMessage='Automatic synchronization stopped: '+reason+'. Both copies are preserved in Settings.';render()}
function autoMergeCopies(base,local,remote,stamp,uid,reason){
 backupBeforeChange('before-auto-sync-device-'+reason,local);
 backupBeforeChange('before-auto-sync-cloud-'+reason,remote);
 const preferred=preferLocalChange(uid,stamp)?'local':'remote';
 const merged=merge3(payloadOf(base||blank()),local,remote,'',preferred);
 cloudMessage='Synchronizing changes from multiple devices automatically';
 return normalized(merged.value);
}
async function cloudRoundTrip(){
 if(!cloud||!cloudUser||cloudConflict)return;
 const uid=cloudUser.id,stored=storedBaseline(uid),resetPending=localStorage.getItem(LOCAL_RESET_PREFIX+uid)==='1';
 const base=resetPending?payloadOf(blank()):stored?.data;
 const remoteRow=await readCloudRow();
 if(!cloudUser||cloudUser.id!==uid)return; // An account switch cannot write another account's data.
 const remote=remoteRow?.data?payloadOf(remoteRow.data):null,stamp=remoteRow?.updated_at||null,local=payloadOf(db);
 if(!remote){
  const written=await writeCloudRow(null,local);
  if(!written){cloudMessage='Another device created cloud data; checking again';return cloudRoundTrip()}
  saveBaseline(uid,local,written);if(resetPending)localStorage.removeItem(LOCAL_RESET_PREFIX+uid);
  cloudStatus=payloadSame(db,local)?'synced':'pending';cloudMessage='Cloud backup saved';if(cloudStatus==='pending')requestCloudSync();return;
 }
 if(resetPending&&!hasContent(local)){
  restoreCloudSnapshot(remote,stamp);localStorage.removeItem(LOCAL_RESET_PREFIX+uid);return;
 }
 if(payloadSame(local,remote)){
  saveBaseline(uid,remote,stamp);if(resetPending)localStorage.removeItem(LOCAL_RESET_PREFIX+uid);
  cloudConflict=null;cloudStatus='synced';cloudMessage='All changes automatically saved';return;
 }
 if(!resetPending&&base&&payloadSame(local,base)) {restoreCloudSnapshot(remote,stamp);return}
 let desired=local;
 if(resetPending||(base&&!payloadSame(remote,base))||(!base&&hasContent(local)&&hasContent(remote))){
  // Concurrent changes, a first-device login, or edits after a local-only reset.
  desired=payloadOf(autoMergeCopies(base,local,remote,stamp,uid,resetPending?'reset':base?'concurrent':'first-login'));
  if(!payloadSame(db,desired)){db=normalized(desired);save(false)}
 }else if(!base&&!hasContent(local)){restoreCloudSnapshot(remote,stamp);return}
 else if(!base&&!hasContent(remote)){desired=local}
 // Optimistic locking ensures a competing device's newer write is not overwritten.
 const written=await writeCloudRow(stamp,desired);
 if(!written){cloudStatus='pending';cloudMessage='Cloud changed during save; automatically retrying';return cloudRoundTrip()}
 saveBaseline(uid,desired,written);if(resetPending)localStorage.removeItem(LOCAL_RESET_PREFIX+uid);
 cloudConflict=null;cloudStatus=payloadSame(db,desired)?'synced':'pending';
 cloudMessage=cloudStatus==='synced'?'All changes automatically saved':'More changes are waiting to save';
 if(cloudStatus==='pending')requestCloudSync();
}

function queueCloudSync(){if(!cloud||!cloudUser)return Promise.resolve();const token=cloudUser.id;
 const operation=cloudSerial.then(async()=>{if(!cloudUser||cloudUser.id!==token||cloudConflict)return;cloudOperationCount++;try{await cloudRoundTrip();cloudRetry=0;cloudError=''}catch(e){cloudStatus='offline';cloudError=String(e.message||e);cloudMessage='Cloud sync failed; local changes are preserved';console.warn('VALOWISH sync:',e);scheduleCloudRetry()}finally{cloudOperationCount--;if(page==='settings')render()}});
 cloudSerial=operation.catch(()=>{});return operation;
}
function requestCloudSync(){if(!cloudUser)return;clearTimeout(cloudTimer);cloudTimer=setTimeout(()=>{if(cloudReady)queueCloudSync().catch(console.warn)},500)}
function scheduleCloudRetry(){if(!cloudUser)return;clearTimeout(cloudRetryTimer);const wait=Math.min(60000,2000*2**Math.min(cloudRetry++,5));cloudRetryTimer=setTimeout(()=>{if(cloudReady&&!cloudConflict)queueCloudSync().catch(console.warn)},wait)}
function selectAccountLocal(user){
 const uid=user.id,previous=localStorage.getItem(ACTIVE_ACCOUNT_KEY);
 if(previous&&previous!==uid){backupBeforeChange('before-account-switch');try{db=normalized(JSON.parse(localStorage.getItem(ACCOUNT_DATA_PREFIX+uid)||'null'))}catch{db=blank()}save(false)}
 else if(!previous){const saved=localStorage.getItem(ACCOUNT_DATA_PREFIX+uid);if(saved){backupBeforeChange('before-account-restore');try{db=normalized(JSON.parse(saved))}catch{}save(false)}}
 try{localStorage.setItem(ACTIVE_ACCOUNT_KEY,uid)}catch{}
 cloudAccountId=uid;const meta=storedBaseline(uid);cloudBaseline=meta?.data||null;cloudRemoteStamp=meta?.updated_at||null;cloudLastSync=meta?.confirmed_at||'';
}
async function activateCloudUser(user){if(!user)return;
 if(cloudUser?.id===user.id&&cloudReady)return;
 if(cloudInitializing&&cloudUser?.id===user.id)return cloudInitializing;
 cloudUser=user;cloudReady=false;cloudStatus='checking';cloudMessage='Restoring your saved VALOWISH cloud data...';
 selectAccountLocal(user);render();
 cloudInitializing=queueCloudSync().then(()=>{cloudReady=true;if(cloudStatus==='pending')requestCloudSync();}).finally(()=>{cloudInitializing=null;render()});
 return cloudInitializing;
}
function detachCloudUser(){clearTimeout(cloudTimer);clearTimeout(cloudRetryTimer);cloudReady=false;cloudUser=null;cloudAccountId=null;cloudBaseline=null;cloudRemoteStamp=null;cloudConflict=null;cloudStatus='local';cloudMessage='Signed out. Changes are stored on this device until you log in.';render()}
// Auth events run outside Supabase's auth callback to avoid auth-lock contention.
async function initCloud(){try{
 if(!window.supabase){await new Promise((ok,fail)=>{const s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2';s.async=true;s.onload=ok;s.onerror=fail;document.head.appendChild(s)})}
 if(!window.supabase?.createClient)throw Error('Cloud library unavailable');
 cloud=window.supabase.createClient(SUPABASE_URL,SUPABASE_KEY,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});
 cloudStatus='checking';cloudMessage='Checking your cloud session...';
 const{data,error}=await cloud.auth.getSession();if(error)throw error;
 if(data?.session?.user)await activateCloudUser(data.session.user);else{cloudStatus='local';cloudMessage='Sign in to back up and synchronize your data';}
 cloud.auth.onAuthStateChange((event,session)=>{setTimeout(()=>{if(session?.user){if(!cloudUser||cloudUser.id!==session.user.id||!cloudReady)activateCloudUser(session.user).catch(console.warn)}else if(event==='SIGNED_OUT')detachCloudUser()},0)});
 cloudPollTimer=setInterval(()=>{if(cloudUser&&cloudReady&&!document.hidden&&!cloudConflict)queueCloudSync().catch(console.warn)},90000);
 window.addEventListener('online',()=>{if(cloudUser){cloudStatus='pending';requestCloudSync()}});
 document.addEventListener('visibilitychange',()=>{if(!document.hidden&&cloudUser&&cloudReady)queueCloudSync().catch(console.warn)});
 window.addEventListener('pagehide',()=>{if(cloudUser&&cloudReady&&!cloudConflict)queueCloudSync().catch(console.warn)});
 render();
 }catch(e){console.warn('Cloud unavailable; locally saved data remains intact',e);cloudStatus='offline';cloudError=String(e.message||e);cloudMessage='Cloud connection unavailable. Local data is still saved.';render()}}
async function auth(action,email,password,name){if(!cloud){await initCloud();if(!cloud)return toast('Cloud connection unavailable')}
 try{cloudBusy=true;cloudMessage=action==='signup'?'Creating account...':'Signing in...';if(page==='settings')render();const result=action==='signup'?await cloud.auth.signUp({email,password,options:{data:{name:name||db.name}}}):await cloud.auth.signInWithPassword({email,password});if(result.error)throw result.error;
 if(action==='signup'&&!result.data.session){cloudMessage='Confirm your email before synchronizing';toast(cloudMessage)}else{await activateCloudUser(result.data.user||result.data.session?.user);toast(cloudStatus==='synced'?'Cloud connected · automatic sync on':'Cloud connected · saving automatically')}
 }catch(e){cloudError=String(e.message||e);cloudMessage=cloudError;toast(cloudMessage)}finally{cloudBusy=false;render()}}
async function pushCloud(){if(!cloudUser)return toast('Sign in to sync');if(cloudConflict)return toast('Automatic sync unavailable; recovery copies are in Settings');cloudStatus='pending';await queueCloudSync();toast(cloudStatus==='synced'?'Cloud verified':'Cloud pending: '+(cloudError||cloudMessage))}
async function pullCloud(){if(!cloudUser)return toast('Sign in first');await queueCloudSync()}
async function resolveCloudConflict(choice){if(!cloudConflict||!cloudUser)return;const{remote,stamp}=cloudConflict;
 if(choice==='download'){downloadBackup('VALOWISH-device-backup.json',db);downloadBackup('VALOWISH-cloud-backup.json',remote);return}
 if(!confirm(choice==='cloud'?'Restore the cloud copy on this device? A recovery snapshot of your current data will be saved locally.': 'Upload this device\'s data as the cloud copy? The current cloud data will be saved to your local recovery snapshots first.'))return;
 if(choice==='cloud'){restoreCloudSnapshot(remote,stamp);return}
 backupBeforeChange('before-replacing-cloud-copy',remote);const expected=stamp;cloudConflict=null;cloudStatus='pending';
 const desired=payloadOf(db);
 try{const written=await writeCloudRow(expected,desired);if(!written){const latest=await readCloudRow();setSyncConflict(latest?.data||{},latest?.updated_at||null,'Cloud changed again. Review before overwriting.');return}saveBaseline(cloudUser.id,desired,written);cloudStatus='synced';cloudMessage='Your device data was uploaded';if(!payloadSame(db,desired))requestCloudSync();render()}
 catch(e){cloudError=String(e.message||e);cloudStatus='offline';cloudMessage='Could not upload: '+cloudError;render()}
}
function downloadBackup(filename,value){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function availableLocalBackups(){const keys=[STORAGE,...OLD].filter(k=>{try{const raw=localStorage.getItem(k);return!!raw&&hasContent(JSON.parse(raw))}catch{return false}});return keys}
function availableRecoverySnapshots(){try{const keys=[];for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(k?.startsWith('valowish_recovery_v19_'))keys.push(k)}return keys.sort().reverse().slice(0,6).map(key=>{const m=JSON.parse(localStorage.getItem(key)||'{}');return{key,description:(m.created_at?new Date(m.created_at).toLocaleString():'Recovery copy')+' · '+String(m.label||'saved copy').replace(/-/g,' ').slice(0,55)}})}catch{return []}}
function restoreRecoverySnapshot(key){if(!key.startsWith('valowish_recovery_v19_'))return;const raw=localStorage.getItem(key);if(!raw)return;try{const record=JSON.parse(raw);if(!record.data||!Array.isArray(record.data.wishlist))throw Error('Invalid recovery copy');if(!confirm('Restore this older local recovery copy? Your current data will be backed up first, then automatic cloud sync will resume.'))return;backupBeforeChange('before-restore-recovery');db=normalized(record.data);save();render();toast('Recovery copy restored; saving to cloud automatically')}catch(e){toast('Recovery copy could not be restored')}}
function restoreLegacyBackup(key){const raw=localStorage.getItem(key);if(!raw)return;if(!confirm('Restore locally saved data from '+key+'? Current data will be backed up first.'))return;
 try{const restored=normalized(JSON.parse(raw));backupBeforeChange('before-legacy-restore');db=restored;save();render();toast('Restored local backup; checking cloud')}catch(e){toast('Could not restore this backup')}}
async function logout(){if(!cloud)return;await cloud.auth.signOut();detachCloudUser();toast('Logged out; local data preserved')}
async function updateAccount(mode){if(!cloud||!cloudUser)return toast('Sign in first');const value=document.getElementById(mode==='email'?'cloud-email':'cloud-password')?.value;if(!value)return;if(mode==='password'&&value.length<6)return toast('At least six characters required');const{error}=await cloud.auth.updateUser(mode==='email'?{email:value}:{password:value});toast(error?error.message:mode==='email'?'Email update requested':'Password changed')}
async function deleteAccount(){if(!cloud||!cloudUser)return;if(!confirm('Permanently delete your cloud account and all associated data?'))return;try{const{error}=await cloud.functions.invoke('delete-account');if(error)throw error;cloudUser=null;cloudReady=false;cloudAccountId=null;db=blank();save(false);render();toast('Cloud account deleted')}catch(e){toast('Deletion failed: '+e.message)}}
render();ensureKind('skins');initCloud().catch(console.error);
